insert into public.quizzes (id, module_id, title) values ('c91a2c2b-ef46-44c7-897e-6b506323405c', '7ba0488d-10a5-42fc-8285-e575939e82e6', 'Quiz: Kaufvertrag und Beschaffung');
insert into public.lessons (module_id, title, goal, explanation, examples, summary, check_questions, position) values ('880d37d4-2ed8-46f0-9123-05d23011907a', 'Das duale System und der Ausbildungsvertrag', 'Du kannst erklären, wie die duale Ausbildung aufgebaut ist und was im Ausbildungsvertrag stehen muss.', array['Die Ausbildung zur Kauffrau oder zum Kaufmann für Büromanagement läuft im dualen System. Du lernst an zwei Orten: praktisch im Ausbildungsbetrieb und theoretisch in der Berufsschule. Die Ausbildung dauert in der Regel drei Jahre.', 'Grundlage ist das Berufsbildungsgesetz (BBiG). Zwischen dir und dem Betrieb besteht ein Ausbildungsvertrag. Der Betrieb muss die wesentlichen Inhalte schriftlich oder elektronisch festhalten, bevor die Ausbildung beginnt. Dazu gehören zum Beispiel Beginn und Dauer, der Ausbildungsberuf, die Vergütung, der Urlaub und die Dauer der Probezeit.', 'Die Prüfungen nimmt die zuständige Stelle ab. Im Bereich Industrie und Handel ist das in der Regel die Industrie- und Handelskammer (IHK).']::text[], array['Dein Betrieb schickt dir den Vertrag vor Ausbildungsbeginn. Du prüfst, ob Probezeit, Urlaub und Vergütung dort stehen.', 'Dienstags bist du in der Berufsschule, der Rest der Woche gehört dem Betrieb. Beides zählt zur Ausbildung.']::text[], 'Duale Ausbildung heißt Betrieb plus Berufsschule. Der Vertrag hält die wichtigsten Bedingungen fest. Die Prüfung läuft über die zuständige Stelle, meist die IHK.', '[{"q":"An welchen zwei Lernorten findet die duale Ausbildung statt?","a":"Im Ausbildungsbetrieb und in der Berufsschule."},{"q":"Welche Stelle ist im Bereich Industrie und Handel in der Regel für die Prüfung zuständig?","a":"Die Industrie- und Handelskammer (IHK)."}]'::jsonb, 0);
insert into public.lessons (module_id, title, goal, explanation, examples, summary, check_questions, position) values ('880d37d4-2ed8-46f0-9123-05d23011907a', 'Probezeit, Berichtsheft und Prüfungen', 'Du kennst die Regeln zur Probezeit und weißt, warum Berichtsheft und Prüfungstermine wichtig sind.', array['Die Probezeit muss mindestens einen Monat und darf höchstens vier Monate dauern. Währenddessen kann das Ausbildungsverhältnis von beiden Seiten ohne Einhaltung einer Frist und ohne Angabe von Gründen gekündigt werden.', 'Das Berichtsheft, auch Ausbildungsnachweis genannt, dokumentiert regelmäßig, was du im Betrieb und in der Schule gelernt hast. Es wird von deinem Ausbilder oder deiner Ausbilderin gegengezeichnet. Ohne ordnungsgemäß geführten Nachweis kannst du nicht zur Abschlussprüfung zugelassen werden.', 'Die Abschlussprüfung ist bei Büromanagement gestreckt: Ein Teil findet etwa zur Mitte der Ausbildung statt, der zweite Teil am Ende. Das Ergebnis des ersten Teils fließt in die Gesamtnote ein. Die genauen Termine gibt deine zuständige Stelle bekannt.']::text[], array['Du schreibst jeden Freitag 20 Minuten im Berichtsheft, was du in der Woche gemacht hast.', 'Zwei Wochen vor dem ersten Prüfungsteil trägst du den Termin in deinen Prüfungsplaner ein.']::text[], 'Probezeit: ein bis vier Monate, in dieser Zeit ohne Frist kündbar. Berichtsheft: Pflicht und Voraussetzung für die Zulassung. Gestreckte Prüfung: zwei Teile, beide zählen.', '[{"q":"Wie lang darf die Probezeit höchstens sein?","a":"Vier Monate. Mindestens muss sie einen Monat betragen."},{"q":"Warum ist das Berichtsheft wichtig?","a":"Es ist der Ausbildungsnachweis und Voraussetzung für die Zulassung zur Abschlussprüfung."}]'::jsonb, 1);
insert into public.lessons (module_id, title, goal, explanation, examples, summary, check_questions, position) values ('a1000626-469f-4b4c-ada3-28d043a5f842', 'Zeitmanagement mit dem Eisenhower-Prinzip', 'Du kannst Aufgaben nach Wichtigkeit und Dringlichkeit sortieren und daraus eine Reihenfolge ableiten.', array['Das Eisenhower-Prinzip teilt Aufgaben in vier Felder ein, je nachdem, ob sie wichtig und ob sie dringend sind.', 'Wichtig und dringend: sofort selbst erledigen. Wichtig, aber nicht dringend: einen Termin dafür einplanen. Dringend, aber nicht wichtig: wenn möglich delegieren. Weder wichtig noch dringend: weglassen oder später erledigen.', 'Im Büro hilft dir das, wenn mehrere Aufgaben gleichzeitig eintreffen, zum Beispiel eine Kundenreklamation, die Terminplanung für nächste Woche und eine Rückfrage zur Kaffeebestellung.']::text[], array['Die Reklamation eines Kunden mit Frist heute: wichtig und dringend, sofort bearbeiten.', 'Die Ablage der Unterlagen vom letzten Quartal: wichtig, aber nicht dringend, du blockst dir dafür Freitagvormittag.']::text[], 'Vier Felder: sofort erledigen, terminieren, delegieren, streichen. Entscheidend ist die ehrliche Einschätzung, was wirklich wichtig ist.', '[{"q":"Was machst du mit einer Aufgabe, die wichtig, aber nicht dringend ist?","a":"Du planst einen festen Termin dafür ein."},{"q":"Was passiert mit Aufgaben, die dringend, aber nicht wichtig sind?","a":"Sie werden, wenn möglich, delegiert."}]'::jsonb, 2);
insert into public.lessons (module_id, title, goal, explanation, examples, summary, check_questions, position) values ('a1000626-469f-4b4c-ada3-28d043a5f842', 'Ablage, Aufbewahrungsfristen und Geschäftsbrief', 'Du kennst die wichtigsten Aufbewahrungsfristen und die Grundregeln für einen Geschäftsbrief nach DIN 5008.', array['Geschäftsunterlagen müssen für festgelegte Zeiträume aufbewahrt werden. Handels- und Geschäftsbriefe sind sechs Jahre aufzubewahren. Buchungsbelege sind nach aktuellem Stand acht Jahre aufzubewahren, Bücher, Jahresabschlüsse und Bilanzen zehn Jahre. Die Frist beginnt in der Regel mit dem Ende des Kalenderjahres, in dem das Dokument entstanden ist.', 'Geschäftsbriefe werden nach DIN 5008 gestaltet. Dazu gehört unter anderem eine Betreffzeile, vor der das Wort „Betreff“ nicht mehr geschrieben wird, sowie eine klare Gliederung in Anrede, Text und Grußformel.', 'Hinweis: Fristen können sich ändern. Prüfe vor der Prüfung die aktuelle Fassung der Vorschriften.']::text[], array['Eine Eingangsrechnung aus dem Jahr 2023 wird nicht im Papierkorb abgelegt, sondern bleibt in der Buchhaltungsablage.', 'Du schreibst „Ihre Anfrage vom 12. Mai“ als Betreffzeile, ohne das Wort „Betreff“ davor.']::text[], 'Briefe sechs Jahre, Buchungsbelege acht Jahre, Jahresabschlüsse zehn Jahre. Die Frist startet am Jahresende. Geschäftsbriefe folgen der DIN 5008.', '[{"q":"Wie lange müssen Handels- und Geschäftsbriefe aufbewahrt werden?","a":"Sechs Jahre."},{"q":"Wann beginnt die Aufbewahrungsfrist in der Regel?","a":"Mit dem Ende des Kalenderjahres, in dem das Dokument entstanden ist."}]'::jsonb, 3);
insert into public.lessons (module_id, title, goal, explanation, examples, summary, check_questions, position) values ('7ba0488d-10a5-42fc-8285-e575939e82e6', 'Zustandekommen des Kaufvertrags', 'Du kannst erklären, wie ein Kaufvertrag entsteht und was Verpflichtungs- und Erfüllungsgeschäft unterscheidet.', array['Ein Kaufvertrag kommt durch zwei übereinstimmende Willenserklärungen zustande: den Antrag und die Annahme. Wer den Antrag stellt, ist an ihn gebunden, solange er nicht ausdrücklich freibleibend ist.', 'Der Kaufvertrag selbst ist das Verpflichtungsgeschäft. Er verpflichtet den Verkäufer, die Ware zu übergeben und das Eigentum zu verschaffen, und den Käufer, den Preis zu zahlen und die Ware abzunehmen. Erst die Übergabe und Zahlung sind das Erfüllungsgeschäft.', 'Wichtig für die Praxis: Ein Angebot mit dem Zusatz „freibleibend“ ist kein verbindlicher Antrag. Die Bestellung des Kunden ist dann der Antrag, und du nimmst ihn mit der Auftragsbestätigung an.']::text[], array['Dein Betrieb bestellt 20 Ordner bei einem Lieferanten. Bestellung und Auftragsbestätigung ergeben den Vertrag.', 'Die Lieferung der Ordner und die Überweisung des Rechnungsbetrags erfüllen den Vertrag.']::text[], 'Antrag plus Annahme ergibt den Vertrag. Der Vertrag ist das Verpflichtungsgeschäft, Lieferung und Zahlung sind das Erfüllungsgeschäft.', '[{"q":"Aus welchen beiden Willenserklärungen besteht ein Kaufvertrag?","a":"Aus Antrag und Annahme."},{"q":"Ist die Lieferung der Ware Verpflichtungs- oder Erfüllungsgeschäft?","a":"Erfüllungsgeschäft."}]'::jsonb, 4);
insert into public.lessons (module_id, title, goal, explanation, examples, summary, check_questions, position) values ('7ba0488d-10a5-42fc-8285-e575939e82e6', 'Mängel und Zahlungsverzug', 'Du kennst die Rechte bei mangelhafter Ware und weißt, wann ein Zahlungsverzug eintritt.', array['Ist die gelieferte Ware mangelhaft, hat der Käufer zunächst Anspruch auf Nacherfüllung, also Nachbesserung oder Ersatzlieferung. Erst wenn das scheitert, kommen Rücktritt, Minderung oder Schadenersatz in Betracht. Bei neuen beweglichen Sachen verjähren die Mängelansprüche in der Regel nach zwei Jahren.', 'Zahlungsverzug tritt bei Fälligkeit und Mahnung ein. Bei Geldforderungen gerät der Schuldner auch ohne Mahnung in Verzug, wenn er nicht innerhalb von 30 Tagen nach Fälligkeit und Zugang der Rechnung zahlt. Steht ein festes Zahlungsdatum im Vertrag, tritt Verzug mit Ablauf dieses Datums ein.', 'Im Büro bedeutet das: Zahlungsziele und Rechnungseingang sauber dokumentieren, damit du Fristen nachweisen kannst.']::text[], array['Die gelieferten Bürostühle haben defekte Rollen. Du verlangst zuerst Ersatz oder Reparatur.', 'Eine Rechnung geht am 3. März ein und ist sofort fällig. Ohne Mahnung tritt der Verzug 30 Tage später ein.']::text[], 'Erst Nacherfüllung, dann Rücktritt, Minderung oder Schadenersatz. Verjährung meist zwei Jahre. Verzug: Mahnung oder 30 Tage nach Fälligkeit und Rechnungszugang.', '[{"q":"Welches Recht hat der Käufer bei einem Mangel zuerst?","a":"Das Recht auf Nacherfüllung (Nachbesserung oder Ersatzlieferung)."},{"q":"Nach wie vielen Tagen tritt bei einer Rechnung ohne Mahnung in der Regel Verzug ein?","a":"30 Tage nach Fälligkeit und Zugang der Rechnung."}]'::jsonb, 5);
insert into public.quiz_questions (quiz_id, question, options, correct_index, explanation, position) values ('8d14bec3-58f5-4f2d-ae83-318039dd3caf', 'Wie lange darf die Probezeit in der Berufsausbildung höchstens dauern?', array['Zwei Monate', 'Drei Monate', 'Vier Monate', 'Sechs Monate']::text[], 2, 'Die Probezeit beträgt mindestens einen und höchstens vier Monate.', 0);
insert into public.quiz_questions (quiz_id, question, options, correct_index, explanation, position) values ('8d14bec3-58f5-4f2d-ae83-318039dd3caf', 'Welche Stelle nimmt bei Kaufleuten für Büromanagement im Bereich Industrie und Handel in der Regel die Prüfung ab?', array['Die Berufsschule', 'Die Industrie- und Handelskammer', 'Das Finanzamt', 'Der Ausbildungsbetrieb']::text[], 1, 'Zuständige Stelle ist im Bereich Industrie und Handel in der Regel die IHK.', 1);
insert into public.quiz_questions (quiz_id, question, options, correct_index, explanation, position) values ('8d14bec3-58f5-4f2d-ae83-318039dd3caf', 'Wo findet die duale Ausbildung statt?', array['Nur im Betrieb', 'Nur in der Berufsschule', 'Im Betrieb und in der Berufsschule', 'An der Universität']::text[], 2, 'Dual bedeutet: Praxis im Betrieb, Theorie in der Berufsschule.', 2);
insert into public.quiz_questions (quiz_id, question, options, correct_index, explanation, position) values ('c91a2c2b-ef46-44c7-897e-6b506323405c', 'Wodurch kommt ein Kaufvertrag zustande?', array['Durch eine einseitige Willenserklärung', 'Durch zwei übereinstimmende Willenserklärungen', 'Nur durch Unterschrift auf Papier', 'Erst durch die Zahlung']::text[], 1, 'Antrag und Annahme sind zwei übereinstimmende Willenserklärungen.', 0);
insert into public.quiz_questions (quiz_id, question, options, correct_index, explanation, position) values ('c91a2c2b-ef46-44c7-897e-6b506323405c', 'Der Kaufvertrag selbst ist ein …', array['Erfüllungsgeschäft', 'Verpflichtungsgeschäft', 'Nichtigkeitsgeschäft', 'Gelegenheitsgeschäft']::text[], 1, 'Der Vertrag verpflichtet beide Seiten, die Erfüllung folgt durch Lieferung und Zahlung.', 1);
insert into public.quiz_questions (quiz_id, question, options, correct_index, explanation, position) values ('c91a2c2b-ef46-44c7-897e-6b506323405c', 'Welche Verjährungsfrist gilt für Mängelansprüche bei neuen beweglichen Sachen in der Regel?', array['6 Monate', '1 Jahr', '2 Jahre', '5 Jahre']::text[], 2, 'Die Mängelansprüche verjähren in der Regel nach zwei Jahren.', 2);
insert into public.quiz_questions (quiz_id, question, options, correct_index, explanation, position) values ('c91a2c2b-ef46-44c7-897e-6b506323405c', 'Wann gerät ein Schuldner bei einer Geldforderung ohne Mahnung in Verzug?', array['Sofort bei Rechnungsdatum', 'Spätestens 30 Tage nach Fälligkeit und Zugang der Rechnung', 'Nach 6 Monaten', 'Nie ohne gerichtliche Mahnung']::text[], 1, 'Nach 30 Tagen ab Fälligkeit und Rechnungszugang tritt Verzug auch ohne Mahnung ein.', 3);
insert into public.quiz_questions (quiz_id, question, options, correct_index, explanation, position) values ('2bf97629-e512-4bed-b5cd-9685f7d6feb1', 'Wie behandelst du nach dem Eisenhower-Prinzip eine Aufgabe, die wichtig und dringend ist?', array['Delegieren', 'Terminieren', 'Sofort selbst erledigen', 'Streichen']::text[], 2, 'Wichtig und dringend gehört an die erste Stelle.', 0);
insert into public.quiz_questions (quiz_id, question, options, correct_index, explanation, position) values ('2bf97629-e512-4bed-b5cd-9685f7d6feb1', 'Wie lange müssen Handels- und Geschäftsbriefe aufbewahrt werden?', array['2 Jahre', '6 Jahre', '8 Jahre', '30 Jahre']::text[], 1, 'Handels- und Geschäftsbriefe: sechs Jahre.', 1);
insert into public.quiz_questions (quiz_id, question, options, correct_index, explanation, position) values ('2bf97629-e512-4bed-b5cd-9685f7d6feb1', 'Welche Aussage zur Betreffzeile nach DIN 5008 stimmt?', array['Das Wort „Betreff“ wird davorgeschrieben', 'Das Wort „Betreff“ entfällt', 'Die Betreffzeile steht unter der Grußformel', 'Eine Betreffzeile ist verboten']::text[], 1, 'Nach DIN 5008 wird das Wort „Betreff“ nicht mehr geschrieben.', 2);
